      const res2 = await t.fetch("/stable", {
        headers: { Cookie: setCookie.split(";")[0] },
      });
      expect(await res2.json()).toMatchObject({ id });
    });
  });

  describe("extraUnsealPasswords", () => {
    // Distinct, and long enough to pass the seal's minPasswordlength check
    const NEW = "new-password".padEnd(40, "n");
    const OLD = "old-password".padEnd(40, "o");
    const OLDER = "older-password".padEnd(40, "p");
    const UNLISTED = "unlisted-password".padEnd(40, "u");
    const DATA = { user: "alice" };

    const config = (more: Partial<SessionConfig> = {}): SessionConfig => ({
      name: "h3-extra",
      password: NEW,
      generateId: () => "new-id",
      ...more,
    });

    const sealedWith = (
      password: string,
      session: Record<string, unknown> = {},
      sealOptions = sealDefaults,
    ) => seal({ id: "sealed-id", createdAt: Date.now(), data: DATA, ...session }, password, sealOptions);

    const legacySealedWith = (password: string, session: Record<string, unknown> = {}) =>
      sealedWith(password, session, {
        ...sealDefaults,
        encryption: { ...sealDefaults.encryption, iterations: 1 },
        integrity: { ...sealDefaults.integrity, iterations: 1 },
      });

    const readRoute = (path: string, sessionConfig: SessionConfig) => {
      t.app.get(path, async (event) => {
        const session = await getSession(event, sessionConfig);
        return { id: session.id, data: session.data };
      });
    };

    it("opens a session sealed with password and does not reseal it", async () => {
      // Control: already works today
      readRoute("/current", config({ extraUnsealPasswords: [OLD] }));
      const sealed = await sealedWith(NEW);
      const res = await t.fetch("/current", { headers: { Cookie: `h3-extra=${sealed}` } });
      expect(await res.json()).toMatchObject({ id: "sealed-id", data: DATA });
      expect(res.headers.getSetCookie()).toHaveLength(0);
    });

    it("opens a session sealed with the first extra password", async () => {
      readRoute("/first-extra", config({ extraUnsealPasswords: [OLD] }));
      const sealed = await sealedWith(OLD);
      const res = await t.fetch("/first-extra", { headers: { Cookie: `h3-extra=${sealed}` } });
      expect(await res.json()).toMatchObject({ id: "sealed-id", data: DATA });
    });

    it("tries extra passwords in declared order and opens with the second", async () => {
      readRoute("/second-extra", config({ extraUnsealPasswords: [OLD, OLDER] }));
      const sealed = await sealedWith(OLDER);
      const res = await t.fetch("/second-extra", { headers: { Cookie: `h3-extra=${sealed}` } });
      expect(await res.json()).toMatchObject({ id: "sealed-id", data: DATA });
    });

    it("opens a session when password is also listed as an extra, without resealing", async () => {
      // Control: already works today
      readRoute("/duplicate", config({ extraUnsealPasswords: [NEW, OLD] }));
      const sealed = await sealedWith(NEW);
      const res = await t.fetch("/duplicate", { headers: { Cookie: `h3-extra=${sealed}` } });
      expect(await res.json()).toMatchObject({ id: "sealed-id", data: DATA });
      expect(res.headers.getSetCookie()).toHaveLength(0);
    });

    it("rejects a session sealed with a password that is not listed", async () => {
      // Control: already works today
      readRoute("/unlisted", config({ extraUnsealPasswords: [OLD] }));
      const sealed = await sealedWith(UNLISTED);
      const res = await t.fetch("/unlisted", { headers: { Cookie: `h3-extra=${sealed}` } });
      const body = await res.json();
      expect(body.id).toBe("new-id");
      expect(body.data).toEqual({});
    });

    it("rejects an empty or short extra password with its index", async () => {
      const { unsealSession } = await import("../src/index.ts");
      const sealed = await sealedWith(OLD);
      for (const [i, short] of ["", "123"].entries()) {
        const extras = [OLD, short];
        const path = `/short-${i}`;
        readRoute(path, config({ extraUnsealPasswords: extras }));
        const res = await t.fetch(path, { headers: { Cookie: `h3-extra=${sealed}` } });
        expect(await res.json()).toMatchObject({ id: "new-id", data: {} });

        await expect(
          unsealSession({} as any, config({ extraUnsealPasswords: extras }), sealed),
        ).rejects.toThrow("extraUnsealPasswords[1]");
      }
    });

    it("reseals a session opened by an extra password with password", async () => {
      readRoute("/reseal", config({ extraUnsealPasswords: [OLD] }));
      const sealed = await sealedWith(OLD);
      const res = await t.fetch("/reseal", { headers: { Cookie: `h3-extra=${sealed}` } });
      expect(await res.json()).toMatchObject({ id: "sealed-id", data: DATA });

      const setCookies = res.headers.getSetCookie();
      expect(setCookies).toHaveLength(1);
      const resealed = decodeURIComponent(setCookies[0].match(/h3-extra=([^;]+)/)![1]);
      expect(await unseal(resealed, NEW, sealDefaults)).toMatchObject({
        id: "sealed-id",
        data: DATA,
      });
    });

    it("opens the resealed cookie without extra passwords on the next request", async () => {
      readRoute("/converge-1", config({ extraUnsealPasswords: [OLD] }));
      const sealed = await sealedWith(OLD);
      const res1 = await t.fetch("/converge-1", { headers: { Cookie: `h3-extra=${sealed}` } });
      const setCookie = res1.headers.getSetCookie()[0];

      readRoute("/converge-2", config());
      const res2 = await t.fetch("/converge-2", { headers: { Cookie: setCookie.split(";")[0] } });
      expect(await res2.json()).toMatchObject({ id: "sealed-id", data: DATA });
      expect(res2.headers.getSetCookie()).toHaveLength(0);
    });

    it("opens a session from the session header with an extra password, without Set-Cookie", async () => {
      readRoute("/header", config({ extraUnsealPasswords: [OLD] }));
      const sealed = await sealedWith(OLD);
      const res = await t.fetch("/header", { headers: { "x-h3-extra-session": sealed } });
      expect(await res.json()).toMatchObject({ id: "sealed-id", data: DATA });
      expect(res.headers.getSetCookie()).toHaveLength(0);
    });

    it("opens a session from the session header with the legacy seal, without Set-Cookie", async () => {
      // Control: already works today. Header sessions are never resealed
      readRoute("/header-legacy", config());
      const sealed = await legacySealedWith(NEW);
      const res = await t.fetch("/header-legacy", { headers: { "x-h3-extra-session": sealed } });
      expect(await res.json()).toMatchObject({ id: "sealed-id", data: DATA });
      expect(res.headers.getSetCookie()).toHaveLength(0);
    });

    it("does not leak internal markers into the session", async () => {
      t.app.get("/markers", async (event) => {
        const session = await getSession(event, config({ extraUnsealPasswords: [OLD] }));
        return {
          id: session.id,
          data: session.data,
          symbols: Object.getOwnPropertySymbols(session).map(String),
        };
      });
      const sealed = await sealedWith(OLD);
      const res = await t.fetch("/markers", { headers: { Cookie: `h3-extra=${sealed}` } });
      const text = await res.text();
      // Positive assertion first, so an empty session cannot pass by accident
      expect(JSON.parse(text)).toMatchObject({ id: "sealed-id", data: DATA });
      expect(JSON.parse(text).symbols).toEqual([]);
      expect(text).not.toContain("h3.internal");
    });

    it("keeps a deploy A config (old password, new extra) able to open new cookies", async () => {
      readRoute("/deploy-a", config({ password: OLD, extraUnsealPasswords: [NEW] }));
      const sealed = await sealedWith(NEW);
      const res = await t.fetch("/deploy-a", { headers: { Cookie: `h3-extra=${sealed}` } });
      expect(await res.json()).toMatchObject({ id: "sealed-id", data: DATA });
    });

    it("rejects a new-password cookie for the old config without extras", async () => {
      // Control: documents why deploy A is needed
      readRoute("/no-deploy-a", config({ password: OLD }));
      const sealed = await sealedWith(NEW);
      const res = await t.fetch("/no-deploy-a", { headers: { Cookie: `h3-extra=${sealed}` } });
      expect(await res.json()).toMatchObject({ id: "new-id", data: {} });
    });

    it("expires a session opened by an extra password after maxAge", async () => {
      const t0 = Date.parse("2030-01-01T00:00:00Z");
      vi.useFakeTimers({ toFake: ["Date"], now: t0 });
      try {
