        const sealed = await sealedWith(OLD, { createdAt: t0 });
        // Positive pair: without it, the expired case below would pass by accident
        const fresh = await t.fetch("/extra-maxage", { headers: { Cookie: `h3-extra=${sealed}` } });
        expect(await fresh.json()).toMatchObject({ id: "sealed-id", data: DATA });

        vi.setSystemTime(t0 + 61_000);
        const expired = await t.fetch("/extra-maxage", {
          headers: { Cookie: `h3-extra=${sealed}` },
        });
        expect(await expired.json()).toMatchObject({ id: "new-id", data: {} });
      } finally {
        vi.useRealTimers();
      }
    });

    it("expires a session opened by an extra password after idleTimeout", async () => {
      const t0 = Date.parse("2030-01-01T00:00:00Z");
      vi.useFakeTimers({ toFake: ["Date"], now: t0 });
      try {
        readRoute("/extra-idle", config({ idleTimeout: 60, extraUnsealPasswords: [OLD] }));
        const sealed = await sealedWith(OLD, { createdAt: t0, lastSeenAt: t0 });
        const fresh = await t.fetch("/extra-idle", { headers: { Cookie: `h3-extra=${sealed}` } });
        expect(await fresh.json()).toMatchObject({ id: "sealed-id", data: DATA });

        vi.setSystemTime(t0 + 61_000);
        const expired = await t.fetch("/extra-idle", {
          headers: { Cookie: `h3-extra=${sealed}` },
        });
        expect(await expired.json()).toMatchObject({ id: "new-id", data: {} });
      } finally {
        vi.useRealTimers();
      }
    });

    it("stamps lastSeenAt with the request time when resealing an extra-password session", async () => {
      const t0 = Date.parse("2030-01-01T00:00:00Z");
      vi.useFakeTimers({ toFake: ["Date"], now: t0 });
      try {
        readRoute("/extra-idle-reseal", config({ idleTimeout: 60, extraUnsealPasswords: [OLD] }));
        const sealed = await sealedWith(OLD, { createdAt: t0, lastSeenAt: t0 });
        vi.setSystemTime(t0 + 5_000);
        const res = await t.fetch("/extra-idle-reseal", {
          headers: { Cookie: `h3-extra=${sealed}` },
        });
        const setCookies = res.headers.getSetCookie();
        expect(setCookies).toHaveLength(1);
        const resealed = decodeURIComponent(setCookies[0].match(/h3-extra=([^;]+)/)![1]);
        expect(await unseal(resealed, NEW, sealDefaults)).toMatchObject({
          lastSeenAt: t0 + 5_000,
        });
      } finally {
        vi.useRealTimers();
      }
    });

    it("opens a legacy session sealed with an extra password and reseals it with current options", async () => {
      readRoute("/extra-legacy", config({ extraUnsealPasswords: [OLD] }));
      const sealed = await legacySealedWith(OLD);
      const res = await t.fetch("/extra-legacy", { headers: { Cookie: `h3-extra=${sealed}` } });
      expect(await res.json()).toMatchObject({ id: "sealed-id", data: DATA });

      const setCookies = res.headers.getSetCookie();
      expect(setCookies).toHaveLength(1);
      const resealed = decodeURIComponent(setCookies[0].match(/h3-extra=([^;]+)/)![1]);
      // Current iterations only: no legacy fallback on this unseal
      expect(await unseal(resealed, NEW, sealDefaults)).toMatchObject({ data: DATA });
    });

    it("rejects a legacy session sealed with an extra password when legacySealFallback is false", async () => {
      const sealed = await legacySealedWith(OLD);

      // Positive pair: same cookie without the flag opens
      readRoute("/legacy-allowed", config({ extraUnsealPasswords: [OLD] }));
      const allowed = await t.fetch("/legacy-allowed", {
        headers: { Cookie: `h3-extra=${sealed}` },
      });
      expect(await allowed.json()).toMatchObject({ id: "sealed-id", data: DATA });

      readRoute("/legacy-rejected", config({ extraUnsealPasswords: [OLD], legacySealFallback: false }));
      const rejected = await t.fetch("/legacy-rejected", {
        headers: { Cookie: `h3-extra=${sealed}` },
      });
      expect(await rejected.json()).toMatchObject({ id: "new-id", data: {} });
      expect(rejected.headers.getSetCookie()).toHaveLength(0);
    });

    it("unsealSession rejects a bad mac prefix with its own error", async () => {
      // Control: already works today. Extras are not tried for this error
      const { unsealSession } = await import("../src/index.ts");
      const sealed = await sealedWith(OLD);
      const badPrefix = sealed.replace(/^[^*]+/, "Fe26.9");
      await expect(
        unsealSession({} as any, config({ extraUnsealPasswords: [OLD] }), badPrefix),
      ).rejects.toThrow("Wrong mac prefix");
    });

    it("unsealSession rejects with Bad hmac value when no password opens the cookie", async () => {
      // Control: already works today
      const { unsealSession } = await import("../src/index.ts");
      const sealed = await sealedWith(UNLISTED);
      await expect(
        unsealSession({} as any, config({ extraUnsealPasswords: [OLD] }), sealed),
      ).rejects.toThrow("Bad hmac value");
    });
  });
});

